func _initialize() -> void:
	for lang in ["tr", "en"]:
		TranslationServer.set_locale(lang)
		print("=== ", lang)
		var run := [_stage("design", 0.0, 1.0), _stage("dev", 1.0, 2.0), _stage("test", 2.0, 3.0)]
		var due := {"kind": "due", "text": "S3", "soon": false, "customer": "Acme", "value": 1, "promise": true}

		# A: running dev, no slot. at 1.5 -> made = 2 + 4 = 6 / 10 = 60%.
		var a := _row(_card("feature", {}, false, run), "active", 1.5)
		_check("A pct", a._stage_pct == tr("PRODUCT_STAGE_PCT").format({"stage": tr("PRODUCT_PHASE_DEV"), "pct": Fmt.percent(60.0, 0)}), a._stage_pct)
		_check("A cell", _txt(a) == a._stage_pct and _cell(a).custom_minimum_size.x == UiTokens.D_W_CARD_SLOT, _txt(a))
		a.set_now(1.99)
		_check("A pct 99", a._stage_pct.contains("99"), a._stage_pct)
		a.set_now(0.5)
		_check("A design running", a._stage_pct.contains(tr("PRODUCT_PHASE_DESIGN")), a._stage_pct)
		a.set_now(3.5)
		_check("A none running -> empty, zero width", _cell(a).get_child_count() == 0 and _cell(a).custom_minimum_size.x == 0.0, _txt(a))

		# B: due slot gives way to the pct and returns after.
		var b := _row(_card("feature", due, false, run), "active", 0.0)
		_check("B at 0.0 design runs, pct shows", b._stage_pct != "" and _txt(b) == b._stage_pct, _txt(b))
		var gap := _row(_card("feature", due, false, [_stage("design", 1.0, 2.0)]), "active", 0.5)
		_check("B due while waiting", _txt(gap) == "PanelContainer", _txt(gap))
		gap.set_now(1.5)
		_check("B pct replaces due", gap._stage_pct != "" and _txt(gap) == gap._stage_pct, _txt(gap))
		gap.set_now(2.5)
		_check("B due returns", _txt(gap) == "PanelContainer" and _cell(gap).custom_minimum_size.x == UiTokens.D_W_CARD_SLOT, _txt(gap))

		# C: late wins over pct and due; tooltip stays across ticks.
		var c := _row(_card("feature", due, true, run), "active", 1.5)
		var tip: String = _cell(c).tooltip_text
		c.set_now(1.7)
		_check("C late wins", c._stage_pct == "" and _txt(c) == tr("PRODUCT_LATE") and tip != "" and _cell(c).tooltip_text == tip, _txt(c))

		# D: carried: cell tip dropped while pct shows, back after.
		var d := _row(_card("feature", {"kind": "carried"}, false, [_stage("dev", 1.0, 2.0)]), "active", 0.5)
		_check("D carried tip", _cell(d).tooltip_text == tr("PRODUCT_CARRIED_TIP") and _cell(d).mouse_filter == Control.MOUSE_FILTER_PASS)
		d.set_now(1.5)
		_check("D pct drops carried tip", _cell(d).tooltip_text == "" and _cell(d).mouse_filter == Control.MOUSE_FILTER_IGNORE and _txt(d) == d._stage_pct, _txt(d))
		d.set_now(2.5)
		_check("D carried returns", _cell(d).tooltip_text == tr("PRODUCT_CARRIED_TIP"))

		# E: fix card in an active sprint gets a slot even with empty slot; plan fix card with empty slot gets none.
		var e := _row(_card("fix", {}, false, run), "active", 1.5)
		_check("E fix active slot", _cell(e) != null and _txt(e) == e._stage_pct, _txt(e))
		var f := _row(_card("fix", {}, false, run), "plan", 0.0)
		f.set_now(1.5)
		_check("F fix plan no slot", f._status_cell == null and f._stage_pct == "")

		# G: plan mode keeps today's slot (empty slot still reserves D_W_CARD_SLOT).
		var g := _row(_card("feature", {}, false, run), "plan", 0.0)
		_check("G plan empty slot width", _cell(g).custom_minimum_size.x == UiTokens.D_W_CARD_SLOT and _cell(g).get_child_count() == 0)
		var h := _row(_card("feature", due, true, run), "plan", 0.0)
		_check("H plan due wins over late", _txt(h) == "PanelContainer")

		# I: widths of the longest strings.
		await process_frame
		var worst := 0.0
		for st in ["design", "dev", "test", "product"]:
			var lab := Label.new()
			var host := Control.new()
			host.theme = load("res://themes/menajer_theme.tres")
			root.add_child(host)
			lab.theme_type_variation = &"CaptionName"
			lab.text = tr("PRODUCT_STAGE_PCT").format({"stage": SprintUiShared.stage_name(st), "pct": Fmt.percent(99.0, 0)})
			host.add_child(lab)
			var w := lab.get_combined_minimum_size().x
			worst = maxf(worst, w)
			print("  width ", lab.text, " = ", w)
		var avail: float = UiTokens.D_W_CARD_INFO - UiTokens.SPACE_L
		var fixed: float = UiTokens.D_ICON_ROW + UiTokens.SPACE_M + UiTokens.D_W_CARD_SLOT + UiTokens.SPACE_M + UiTokens.SPACE_M + UiTokens.D_AVATAR_ROW_SM
		print("  worst ", worst, " slot ", UiTokens.D_W_CARD_SLOT, " room before the column edge ", avail - fixed)
	print("PROBE fails=", fails)
	quit(1 if fails > 0 else 0)
