## Yıldız bağlamı: beklenti müşterinin yıldızına bağlıdır, evreye değil. MVP'den hemen sonra ürün sayfası Çekirdek'i Zayıf
## okur ama cümle 1★'a yettiğini söyler; evre geçişi hiçbir adayın ve hesabın U'sunu oynatmaz; MVP 1★ adayda 70, aynı MVP 2★
## adayda 70'in altındadır, aynı ürün 1★, 2★, 3★ adayda azalan U verir; Ar-Ge'nin gizli hattı İlk kullanım'a bir boş hat katınca
## beklenti aynı kalır, alanın seviyesi yarıya iner ve onu bekleyen adayın U'su düşer; B2C'de kitle iki yıldız satırı arasında
## geçerken U sürekli kalır, ürün sayfasının referansı ise kitle 2★'ın altındayken de 2★ satırını okur.
##
## FALSİFİKASYON: ProductQuality.expectation'ın sonundaki `minf(value, top)`'u `minf(value + 0.1 * (GameState.phase - 1), top)` yap →
## evre iddiası FAIL; `_star_value`'daki `[2, "emphasis"]` hücresini `return 1.0 / lines` yap → gizli hat iddiası FAIL; `_audience_fit`'in
## sonunu `return upper` yap → süreklilik iddiası FAIL; `next_ratio`'da sıfır beklentinin üst yıldıza dönüşünü sil → sıfıra bölme
## iddiası FAIL; `_role`'de sektörsüz B2B'yi `rest` oku → sayfa referansı iddiası FAIL; `_value`'de `maxf(star, PAGE_STAR)` yerine
## `star` oku → B2C sayfa referansı iddiası FAIL; `ProductLines.register_runtime_line`dan `memo.clear()`i sil → gizli hat iddiası FAIL;
## `capabilities` önbelleğini `SprintCatalog`ta bir statik değişkene taşı ve yalnız `register_runtime_line` boşaltsın → yeniden yükleme iddiası FAIL.
static func _case_fit_star_context() -> String:
	_seed_sprint_live("erp")
	var asked := func(star: int, sector: String) -> Prospect:
		var p := Prospect.new()
		p.id = "lead_ctx_%d_%s" % [star, sector]
		p.company_name = p.id
		p.industry = sector
		p.star = star
		return p
	var said := func(key: String, args: Dictionary) -> String:
		return TranslationServer.translate(key).format(args)

	# MVP'den hemen sonra: Çekirdek 0,6. Sayfa 2★ şirketin referansını okur, cümle MVP'nin 1★'a yettiğini söyler.
	if ProductQuality.expectation("core", {"star": 1}) != 0.6 or ProductQuality.expectation("core") != 1.25 \
			or ProductQuality.expectation("trust") != 1.0 or ProductQuality.expectation("integrations") != 1.0 \
			or ProductQuality.expectation("revenue") != 0.0:
		return "the page reference reads core %.2f at 1 star and %.2f on the page, trust %.2f, integrations %.2f; want 0.6, 1.25, 1 and 1" % [
			ProductQuality.expectation("core", {"star": 1}), ProductQuality.expectation("core"),
			ProductQuality.expectation("trust"), ProductQuality.expectation("integrations")]
	if ProductQuality.word("core") != "weak" or ProductQuality.serves("core") != 1 \
			or SprintCatalog.area_sentence("core") != said.call("PRODUCT_STAR_SERVES", {"star": 1, "next": 2}):
		return "right after the MVP Core reads '%s', serves %d, says '%s'; want Weak, 1 and the 1 star sentence" % [
			ProductQuality.word("core"), ProductQuality.serves("core"), SprintCatalog.area_sentence("core")]
	if ProductQuality.next_star() != 2:
		return "right after the MVP the next star reads %d, want 2" % ProductQuality.next_star()
	if SprintCatalog.area_sentence("integrations") != said.call("PRODUCT_STAR_SKIPPED", {}) \
			or ProductQuality.word("integrations") != "none":
		return "an empty Integrations reads '%s' and says '%s'; want None and the line that 1 star companies do not look at it" % [
			ProductQuality.word("integrations"), SprintCatalog.area_sentence("integrations")]
	# Sayfanın referansı on üç sektörün en yükseğidir: her yıldızda her alan için.
	for star in [1, 2, 3]:
		for area in SprintCatalog.area_ids():
			var highest: float = 0.0
			for sector in ProductQuality.TABLE:
				highest = maxf(highest, ProductQuality.expectation(area, {"star": star, "sector": sector}))
			if highest != ProductQuality.expectation(area, {"star": star}):
				return "%s at %d star reads %.2f on the page and %.2f at its highest sector" % [
					area, star, ProductQuality.expectation(area, {"star": star}), highest]

	# Sıradaki yıldız: MVP'den sonra lider ve PM'in hedefi 2★'ın baktığı boş bir alana bakar. Çekirdek MVP'nin altına inince
	# sıradaki yıldız 1'dir ve 1★'ın bakmadığı alan 2★'ın değeriyle tartılır: sıfıra bölme olmaz, hedef seçilince şerit 0 kare der.
	if SprintCatalog.pm_goal() not in ["onboarding", "integrations", "trust"]:
		return "right after the MVP the PM's goal reads '%s', want an empty area the next star looks at" % SprintCatalog.pm_goal()
	var wobble: String = SprintCatalog.capabilities("core")[0]
	ProductState.set_line_tier(wobble, 0)
	for line_id in SprintCatalog.capabilities("trust"):
		ProductState.set_line_tier(line_id, 1)
	SprintSystem.pick_goal(SprintCatalog.pm_goal())
	var strip: Dictionary = ProductModel._goal()
	SprintSystem.pick_goal("")
	if ProductQuality.next_star() != 1 or not is_equal_approx(ProductQuality.next_ratio("trust"), 1.0) \
			or not is_equal_approx(ProductQuality.next_ratio("core"), 0.4 / 0.6) \
			or strip.area_id not in ["onboarding", "integrations"] or strip.meter.now != 0:
		return "below the MVP the next star reads %d, Trust %.2f and Core %.2f of it, the strip %s; want 1, 1, 0.67 and an empty area at 0" % [
			ProductQuality.next_star(), ProductQuality.next_ratio("trust"), ProductQuality.next_ratio("core"), strip]
	ProductState.set_line_tier(wobble, 1)
	for line_id in SprintCatalog.capabilities("trust"):
		ProductState.set_line_tier(line_id, 0)

	var mvp_1: Dictionary = ProductQuality.prospect_fit(asked.call(1, "logistics"))
	var mvp_2: Dictionary = ProductQuality.prospect_fit(asked.call(2, "logistics"))
	if mvp_1.value != 70 or mvp_1.loss_area != "" or mvp_2.value >= 70 or mvp_2.loss_area == "":
		return "the MVP reads U %d (loss '%s') for a 1 star and %d (loss '%s') for a 2 star; want 70 and nothing lacking, then under 70 with a lacking area" % [
			mvp_1.value, mvp_1.loss_area, mvp_2.value, mvp_2.loss_area]

	# Evre geçişi hiçbir adayın ve hesabın U'sunu, sayfanın kelimesini ve cümlesini oynatmaz.
	var account: Customer = _sign_fixture(asked.call(3, "health"), 6000, 70)
	var guest: Prospect = asked.call(2, "construction")
	var snapshot := func() -> Array:
		return [ProductQuality.prospect_fit(guest), ProductQuality.account_fit(account), ProductQuality.word("core"),
			SprintCatalog.area_sentence("core"), ProductQuality.next_star(), ProductQuality.expectation("core")]
	var before: Array = snapshot.call()
	for phase in [2, 3]:
		GameState.phase_gate_ready = true
		GameState.pending_next_phase = phase
		GameState.advance_phase()
		if GameState.phase != phase:
			return "fixture: the phase did not advance to %d" % phase
		if snapshot.call() != before:
			return "the move to phase %d changed what a prospect, an account or the page reads: %s -> %s" % [
				phase, before, snapshot.call()]

	# Aynı ürün büyüdükçe büyük şirketin çıtası yükselir: 1★, 2★, 3★ adayda azalan U.
	for line_id in ProductLines.line_ids("erp"):
		ProductState.set_line_tier(String(line_id), 1)
	var by_star: Array = [1, 2, 3].map(func(star: int) -> int:
		return ProductQuality.prospect_fit(asked.call(star, "logistics")).value)
	if not (by_star[0] > by_star[1] and by_star[1] > by_star[2]):
		return "one product reads U %s for a 1, 2 and 3 star prospect, want it falling" % [by_star]

	# Ar-Ge'nin gizli hattı İlk kullanım'ı iki hatlı yapar: beklenti aynı kalır, alanın seviyesi (boş hat) yarıya iner ve onu bekleyen
	# adayın U'su düşer.
	var builder: Prospect = asked.call(2, "construction")
	var u_before: int = ProductQuality.prospect_fit(builder).value
	var exp_before: float = ProductQuality.expectation("onboarding")
	if exp_before != 1.0 or not ProductLines.register_runtime_line(ResearchTree.hidden_line_raw("line_hidden_self_serve"), "erp"):
		return "fixture: Onboarding reads %.2f before the hidden line, or the line did not register" % exp_before
	if ProductQuality.expectation("onboarding") != 1.0 or ProductQuality.level("onboarding") != 0.5 \
			or ProductQuality.prospect_fit(builder).value >= u_before:
		return "with the hidden line open Onboarding expects %.2f (want 1) at level %.2f (want 0.5) and the prospect who looks at it reads U %d, was %d (want lower)" % [
			ProductQuality.expectation("onboarding"), ProductQuality.level("onboarding"), ProductQuality.prospect_fit(builder).value, u_before]
	# `capabilities` önbelleği hat kümesiyle birlikte düşer: çalışma anı hattı eklenince boşalır, yeniden yükleme hattı da önbelleği de siler.
	ProductLines.reload()
	if SprintCatalog.capabilities("onboarding").size() != 1 or ProductQuality.level("onboarding") != 1.0:
		return "a reload keeps the hidden line: Onboarding holds %d lines at level %.2f, want 1 and 1" % [
			SprintCatalog.capabilities("onboarding").size(), ProductQuality.level("onboarding")]

	# B2C: kitle 1.000'e kadar 1★ satırını, 10.000'de 2★'ı, 50.000'den sonra 3★'ı okur; aradaki geçişte U süreklidir. Ürün sayfasının
	# referansı kitlenin yıldızı ile 2★'ın büyüğünü okur.
	SaveManager.reset_all_owners()
	GameState.initialize_run({"seed": 424242})
	_seed_sprint_live("note_tool")
	var audience := func(n: float) -> void:
		GameState.set_flag("b2c_audience", n)
	var u_at := func(n: float) -> int:
		audience.call(n)
		return ProductQuality.fit({"market": "b2c", "sector": ""}).value
	var row_u := func(star: int) -> int:
		return ProductQuality.fit({"market": "b2c", "sector": "", "star": star}).value
	audience.call(1000.0)
	var at_1k: float = ProductQuality.expectation("core", {"audience": true})
	audience.call(10000.0)
	var at_10k: float = ProductQuality.expectation("core", {"audience": true})
	audience.call(sqrt(1000.0 * 10000.0))
	var between: float = ProductQuality.expectation("core", {"audience": true})
	audience.call(80000.0)
	var at_80k: float = ProductQuality.expectation("core", {"audience": true})
	if at_1k != 0.6 or at_10k != 1.25 or at_80k != 2.0 or not (between > 0.6 and between < 1.25):
		return "the audience reads Core %.3f at 1k, %.3f at 10k, %.3f halfway in between and %.3f at 80k; want 0.6, 1.25, in between and 2" % [
			at_1k, at_10k, between, at_80k]
	# Ürün sayfasının referansı kitle 2★'a varana kadar 2★ satırıdır (Çekirdek 1,25, İlk kullanım 1), sonra kitleyi izler (2 ve 1,5).
	var page := func(n: float) -> Array:
		audience.call(n)
		return [ProductQuality.expectation("core"), ProductQuality.expectation("onboarding")]
	var near := func(got: Array, want: Array) -> bool:
		return is_equal_approx(got[0], want[0]) and is_equal_approx(got[1], want[1])
	var small: Array = page.call(200.0)
	var halfway: Array = page.call(sqrt(1000.0 * 10000.0))
	var big: Array = page.call(80000.0)
	if not near.call(small, [1.25, 1.0]) or not near.call(halfway, [1.25, 1.0]) or not near.call(big, [2.0, 1.5]):
		return "the page reads Core and Onboarding %s at 200 users, %s at 3,162 and %s at 80k; want [1.25, 1], [1.25, 1] and [2, 1.5]" % [
			small, halfway, big]
	if u_at.call(1000.0) != 70 or u_at.call(10000.0) != row_u.call(2) or u_at.call(50000.0) != row_u.call(3) \
			or u_at.call(200.0) != 70 or u_at.call(90000.0) != row_u.call(3):
		return "the audience at 1k, 10k, 50k reads U %d, %d, %d; want 70 and the 2 and 3 star rows %d, %d" % [
			u_at.call(1000.0), u_at.call(10000.0), u_at.call(50000.0), row_u.call(2), row_u.call(3)]
	var last: int = u_at.call(500.0)
	var n: float = 500.0
	while n < 100000.0:
		n *= 1.02
		var u: int = u_at.call(n)
		if absi(u - last) > 1:
			return "the audience crossed %d users and U jumped from %d to %d in one 2 percent step" % [roundi(n), last, u]
		last = u
	# Kelime ve cümle sayfanın referansını okur: küçük kitlede de MVP 2★ satırına yetmez; Çekirdek 2★ satırına (1,25) varınca 500'de
	# yeter (1,2 yetmez, 1,4 yeter), kitle 3★ satırına (2) inince yetmez.
	audience.call(500.0)
	if ProductQuality.word("core") != "weak" or SprintCatalog.area_sentence("core") != said.call("PRODUCT_AUDIENCE_OUTGROWN", {}):
		return "500 users read the MVP Core '%s' saying '%s'; want Weak and users want more, the page asks the 2 star row of a small audience too" % [
			ProductQuality.word("core"), SprintCatalog.area_sentence("core")]
	var core_lines: Array = SprintCatalog.capabilities("core")
	for i in core_lines.size():
		ProductState.set_line_tier(core_lines[i], 2 if i < 1 else 1)
	if ProductQuality.word("core") != "weak" or SprintCatalog.area_sentence("core") != said.call("PRODUCT_AUDIENCE_OUTGROWN", {}):
		return "500 users read Core at 1.2 '%s' saying '%s'; want Weak, just under the 2 star row" % [
			ProductQuality.word("core"), SprintCatalog.area_sentence("core")]
	ProductState.set_line_tier(core_lines[1], 2)
	if ProductQuality.word("core") != "enough" or SprintCatalog.area_sentence("core") != said.call("PRODUCT_AUDIENCE_ENOUGH", {}):
		return "500 users read Core at 1.4 '%s' saying '%s'; want Enough and the audience is served" % [
			ProductQuality.word("core"), SprintCatalog.area_sentence("core")]
	audience.call(80000.0)
	if ProductQuality.word("core") != "weak" or SprintCatalog.area_sentence("core") != said.call("PRODUCT_AUDIENCE_OUTGROWN", {}):
		return "80,000 users read Core at 1.4 '%s' saying '%s'; want Weak and the audience has outgrown it" % [
			ProductQuality.word("core"), SprintCatalog.area_sentence("core")]
	# Yayından önce kitle yoktur: alan kitleye yetip yetmediğini söylemez.
	GameState.set_flag("mvp_shipped", false)
	audience.call(0.0)
	if SprintCatalog.area_sentence("core") != "" or SprintCatalog.area_sentence("growth") != "":
		return "before the launch Core says '%s' and Growth '%s'; want no audience sentence" % [
			SprintCatalog.area_sentence("core"), SprintCatalog.area_sentence("growth")]
	return ""


## Ölçek: ürün uyumu alanın seviyesinden ve müşterinin bağlamından okunur, ekibin ya da defterin büyüklüğü U'ya girmez. Aynı alan
## seviyeleriyle 1, 6 ve 50 kişilik ekipte ve 1, 30 ve 330 hesapta her sektörün her yıldızdaki adayının U'su, bir hesabın U'su ve
## pazarın U'su aynı kalır. Bütün alanlar en üst kademedeyken her yıldızda her sektörün adayı U 100 okur, B2C'de her kitlede de
## (kesikten ötesinin uyumu artırmadığı formül düzeyinde `product_fit_table`ta; burada canlı hattan).
##
## FALSİFİKASYON: `ProductQuality.level`ın dönüşünü `/ maxf(1.0, CustomerRegistry.account_count() / 30.0)` ile böl → defter iddiası
## FAIL; `fit_from_levels`ın `uyum`una `+ 0.002 * CharacterRegistry.count_employees()` ekle → ekip iddiası FAIL; `RATIO_CAP`i 1,4 yap
## → "en üst kademede 100" iddiası FAIL.
static func _case_fit_scale() -> String:
	_seed_sprint_live("erp")
	# Karışık bir ürün: U sektöre ve yıldıza göre değişir.

		SprintCatalog.in_product("line_shared_security"): {"accounts": 4, "seats": 340, "top_id": "co_aa", "top_seats": 100},
		SprintCatalog.in_product("line_shared_mobile"): {"accounts": 2, "seats": 50, "top_id": "co_a", "top_seats": 40},
	}
	for line in want:
		if SprintCatalog.line_impact(line) != want[line]:
			return "%s reads %s, want %s" % [line, SprintCatalog.line_impact(line), want[line]]
	ProductState.add_bugs("line_erp_ledger", 6)
	var card: Dictionary = SprintCatalog.card_by_id("fix:line_erp_ledger")
	var part: Dictionary = SprintCatalog.card_effect(card)[0]
	if part != {"k": "bugs", "n": 6, "accounts": 5, "users": 350, "top": "Firm co_aa", "top_users": 100}:
		return "the fix card of 6 bugs reads %s, want 5 accounts, 350 users, Firm co_aa with 100" % [part]
	var text: String = SprintUiShared.bugs_text(part)
	if not text.begins_with("6 ") or not text.contains("350") or not text.contains("Firm co_aa") or not text.ends_with(")"):
		return "the fix card line reads '%s', want 6 bugs, 350 users and the largest account with its seats" % text
	return ""


## Beş B2B hesabı (kimlik, sektör, koltuk, MRR, durum): Çekirdeğin ve Entegrasyonlar'ın hattı beşini (350 koltuk), Güven'in hatları emlak
## hesabı dışındaki dördünü (310) kullanır. En büyük hesap co_aa'dır (koltuk eşitliğinde MRR, sonra kimlik).
static func _seed_line_accounts() -> void:
	for row in [["co_a", "real_estate", 40, 4000, "active"], ["co_zz", "logistics", 100, 9000, "active"],
			["co_aa", "retail", 100, 9000, "active"], ["co_00", "healthcare", 100, 8000, "active"],
			["co_try", "legal", 10, 1000, "trial"]]:
		var c: Customer = _add_customer(row[0], "Firm " + row[0])
		c.industry = row[1]
		c.seats = row[2]
		c.mrr = row[3]
		c.status = row[4]


## Hata sayısı: modülün düzeltme adayı yalnız hatası olan hat için vardır, kartın hata sayısı hattın açık hatasıdır ve metni
## (`fix_text`) hata, hesap ve kullanıcı sayısını ve B2B'de en büyük hesabı söyler; Destek raporunun hat satırı (`bug_row_of`) hattın
## adını, açık hatayı, hesap ve kullanıcı sayısını söyler (B2C'de hesapsız), ipucu geçen haftanın sayısını ve B2B'de en büyük hesabı;
## `delta` son haftalık tikin görüntüsüne göre değişimdir (okun yönü). Alan cümlesi aynı toplamı söyler ve araştırmadan sonraki iki
## haftada kullanıcıların sözünü sonuna ekler, sonra düşürür.
## FALSİFİKASYON: ProductModel._module_card'da `bugs`i `0` yap → sayı iddiası FAIL, `fix_text`i `""` yap → metin iddiası FAIL; kilitsiz
## adaylar süzgecini hatasız hatları da alacak biçimde gevşet (SprintCatalog.candidates'ta `bugs.has(line_id)`yi sil) → hatasız hat
## iddiası FAIL; ProductState.open_bugs_delta yerine `0` ver → ok iddiası FAIL; bug_row_of'ta en büyük hesabın ipucu satırını sil →
## ipucu iddiası FAIL; SprintCatalog.area_sentence'ta araştırma penceresinin `<=`'sini `<` yap ya da bir sprint uzat (`+ 1`) →
## pencere iddiası FAIL, araştırma cümlesini hiç ekleme → söz iddiası FAIL, hata sayısı cümlesini düşür → toplam iddiası FAIL;
## SprintUiShared.impact_bits'te `int(part.accounts) >= 0` denetimini `true` yap → B2C satırı iddiası FAIL.
static func _case_product_bug_rows_read_the_store() -> String:
	_seed_sprint_live("erp")
	_seed_line_accounts()
	var fixes := func() -> Array:
		var core: Array = ProductModel.live().modules.filter(func(m: Dictionary) -> bool: return m.id == "core")
		return [] if core.is_empty() else core[0].candidates.filter(func(c: Dictionary) -> bool: return c.id.begins_with("fix:"))
	if not fixes.call().is_empty():
		return "a product with no open bugs offered the fix candidates %s" % [fixes.call()]
	ProductState.add_bugs("line_erp_ledger", 8)
	ProductState.add_bugs("line_erp_stock", 3)
	ProductState.add_bugs("line_erp_cashflow", 1)
	# A week ago the ledger had 6 and the stock 5; the cash flow had none.
	GameState.set_flag(ProductState.OPEN_BUGS_PREV, {"line_erp_ledger": 6, "line_erp_stock": 5})
	var lines: Array = ["line_erp_ledger", "line_erp_stock", "line_erp_cashflow"]
	var read: Array = fixes.call()
	if read.size() != lines.size():
		return "the core module offers %d fix cards, want the %d lines with open bugs and none without" % [read.size(), lines.size()]
	var rows: Array = []
	for line in lines:
		var card: Array = read.filter(func(c: Dictionary) -> bool: return c.id == "fix:" + line)
		var bugs: int = ProductState.line_bugs(line)
		if card.size() != 1 or card[0].bugs != bugs:
			return "the %s fix card reads %s, want its %d open bugs" % [line, card, bugs]
		if card[0].fix_text != SprintUiShared.bugs_text(SprintCatalog.bugs_part(line, bugs)) \
				or not String(card[0].fix_text).begins_with(SprintUiShared.count("PRODUCT_FX_BUGS", bugs)):
			return "the %s fix card's text reads '%s', want its bug count first" % [line, card[0].fix_text]
		rows.append(ProductModel.bug_row_of(SprintCatalog.cap_name(line), SprintCatalog.bugs_part(line, bugs),
			ProductState.open_bugs_delta(line)))
	if not String(read.filter(func(c: Dictionary) -> bool: return c.id == "fix:line_erp_ledger")[0].fix_text).contains("Firm co_aa"):
		return "the ledger fix card does not name the largest account"
	var ledger: String = SprintUiShared.SEP.join([SprintCatalog.cap_name(lines[0]),
		SprintUiShared.count("PRODUCT_BUG_COUNT", 8), SprintUiShared.count("PRODUCT_ACCOUNT_COUNT", 5),
		SprintUiShared.count("PRODUCT_USER_COUNT", 350)])
	if rows[0].text != ledger:
		return "the ledger row reads '%s', want '%s'" % [rows[0].text, ledger]
	if [rows[0].delta, rows[1].delta, rows[2].delta] != [2, -2, 1]:
		return "the rows' changes read %s, want 2 (6 to 8), -2 (5 to 3) and 1 (0 to 1)" % [[rows[0].delta, rows[1].delta, rows[2].delta]]
	if not rows[0].tip.contains("Firm co_aa") or not rows[0].tip.contains("100") \
			or not rows[0].tip.contains(SprintUiShared.count("PRODUCT_BUG_COUNT", 6)):
		return "the ledger row's tip reads '%s', want last week's 6 and the largest account with its seats" % rows[0].tip
	var b2c: Dictionary = ProductModel.bug_row_of("Sync", {"k": "bugs", "n": 5, "accounts": -1, "users": 300, "top": "",
		"top_users": 0}, -1)
	if b2c.text != SprintUiShared.SEP.join(["Sync", SprintUiShared.count("PRODUCT_BUG_COUNT", 5),
			SprintUiShared.count("PRODUCT_USER_COUNT", 300)]) or b2c.tip.contains("\n"):
		return "a B2C row reads %s, want its users only and no account line in the tip" % [b2c]
	var said: String = SprintCatalog.area_sentence("core")
	if not said.contains(SprintUiShared.count("PRODUCT_BUG_COUNT", 12)):
		return "the core sentence reads '%s', want the 12 open bugs of its three lines" % said
	# The users' words stay for the sprint after the research (a sprint is two weeks, so two weeks) and go after it.
	var voice: String = TranslationServer.translate("PRODUCT_RESEARCH_VOICE_CORE")
	GameState.product.research_done["core"] = SprintSystem.sprint_number() - 1
	if not SprintCatalog.area_sentence("core").ends_with(voice):
		return "a sprint after the research the sentence reads '%s', want the users' words at its end" % SprintCatalog.area_sentence("core")
	GameState.product.research_done["core"] = SprintSystem.sprint_number() - 2
	if SprintCatalog.area_sentence("core").contains(voice):
