free_mb () {
	vm_stat | awk '/page size of/ {ps=$8} /Pages (free|inactive|speculative)/ {gsub("\\.","",$NF); p+=$NF} END {print int(p*ps/1048576)}'
}
pressure () {
	sysctl -n kern.memorystatus_vm_pressure_level 2> /dev/null || echo 1
}
mem_ok () {
	local f
	f=$(free_mb) 
	[ "${f:-0}" -ge "$FREE_MIN_MB" ] && [ "$(pressure)" -lt 4 ] || {
		echo "STOP free=${f}MB pressure=$(pressure)"
		return 1
	}
}
godot_cap () {
	[ "$(pressure)" -ge 2 ] && echo 1 || echo "$GODOT_MAX"
}
godots () {
	pgrep -x Godot | wc -l | tr -d ' '
}
gd () {
	local ad="$1" tree="$2" 
	shift 2
	if [ -d "$K/sessiz" ] && ! grep -q "^$ETIKET" "$K/sessiz/sahip" 2> /dev/null
	then
		echo "WAIT sessiz: $(cat "$K/sessiz/sahip" 2>/dev/null)"
		return 99
	fi
	mem_ok || return 98
	[ "$(godots)" -lt "$(godot_cap)" ] || {
		echo "WAIT godot=$(godots) cap=$(godot_cap)"
		return 97
	}
	mkdir -p "$S/home_$ad"
	(
		cd "$tree" && HOME="$S/home_$ad" "$GODOT" "$@"
	)
}
gdw () {
	local rc
	while :
	do
		gd "$@"
		rc=$? 
		case $rc in
			(97 | 98 | 99) sleep 20 ;;
			(*) return $rc ;;
		esac
	done
}
