## Alanın sözcüğü ürün sayfasının referansını okur (B2B'de 2★, B2C'de kitlenin yıldızı ile 2★'ın büyüğü): seviye 0 Yok, referansın
## altı Zayıf, referans ile referans + 1 arası Yeterli, ondan sonrası Güçlü; küçük kitlede de 2★ satırı okunur.
##
## FALSİFİKASYON: `ProductQuality.word_for`da `expect + 1.0`'ı `expect + 1.5` yap → Güçlü sınırı iddiası FAIL; `lvl < expect`'i
## `lvl <= expect` yap → Yeterli sınırı iddiası FAIL; `lvl <= 0.0` dalını sil → Yok iddiası FAIL; `_value`de `maxf(star, PAGE_STAR)`
## yerine `star` oku → küçük kitle iddiası FAIL.
static func _case_product_area_word() -> String:
	GameState.set_flag("mvp_shipped", true)
	GameState.set_flag("mvp_market_type", "b2b")
	_seed_b2b_lines("erp", 0)
	# [alan, hatların kademeleri, kelime]: ürün sayfasının referansında Çekirdek 1,25, Entegrasyonlar 1, İlk kullanım 1, Güven 1;
	# Çekirdek'in beş hattı var, Güven'in iki.
	var rows := [
		["core", [1, 1, 1, 0, 0], "weak"],        # MVP: 0,6 / 1,25
		["core", [1, 1, 1, 1, 1], "weak"],        # 1 / 1,25
		["core", [2, 1, 1, 1, 1], "weak"],        # 1,2 / 1,25: referansın hemen altı
		["core", [2, 2, 1, 1, 1], "enough"],      # 1,4 / 1,25: referans aşıldı
		["core", [2, 2, 2, 2, 1], "enough"],      # 1,8 / 1,25
		["core", [2, 2, 2, 2, 2], "enough"],      # 2 / 1,25
		["core", [3, 3, 3, 3, 3], "strong"],      # referans + 1'in üstü
		["core", [0, 0, 0, 0, 0], "none"],
		["integrations", [2], "strong"],          # 2 / 1: referans + 1'e tam varır
		["onboarding", [1], "enough"],            # 1 / 1: referansta
		["trust", [1, 0], "weak"],                # 0,5 / 1
		["trust", [1, 1], "enough"],
		["trust", [0, 0], "none"],
	]
	for row in rows:
		var lines: Array = SprintCatalog.capabilities(row[0])
		for i in lines.size():
			ProductState.set_line_tier(lines[i], int(row[1][i]))
		var got: String = ProductQuality.word(row[0])
		if got != row[2]:
			return "%s at tiers %s reads '%s'; want '%s'" % [row[0], row[1], got, row[2]]
	# Küçük kitleli B2C ürünün sayfası da 2★ satırını okur: İlk kullanım 1 ister (yeter).
	_seed_b2c()
	_set_area_tiers({"onboarding": 1})
	if ProductQuality.expectation("onboarding") != 1.0:
		return "fixture: the page asks %.2f of Onboarding in a 200 user audience, want 1" % ProductQuality.expectation("onboarding")
	if ProductQuality.word("onboarding") != "enough":
		return "Onboarding at its reference in a small audience reads '%s', want 'enough'" % ProductQuality.word("onboarding")
	return ""


## İş profili: her hattın profili var ve dağılım tutuyor: kimlik hatları geliştirme 2 · test 1 · tasarım 2, paylaşılan hatlar
## geliştirme 1 · test 2 · tasarım 1, Ar-Ge'nin gizli hatları geliştirme 1 · test 2 · tasarım 1. Doğrulayıcı üç değerin dışını
## ve eksik profili reddeder.
##
## FALSİFİKASYON: shared.json'da bir hattın profilini değiştir → dağılım iddiası FAIL. _build_line'daki PROFILES kontrolünü sil →
## kayıt reddedilmez, FAIL.
static func _case_product_line_profiles() -> String:
	ProductLines.reload()
	var seen: int = 0
	for sub in ProductLines.subtypes():
		var identity: Dictionary = {}
		var shared: Dictionary = {}
		for id in ProductLines.line_ids(sub):
			var profile: String = ProductLines.work_profile(id)
			if not ProductLines.PROFILES.has(profile):
				return "%s carries profile '%s'" % [id, profile]
			var tally: Dictionary = shared if bool(ProductLines.line(id).shared) else identity
			tally[profile] = int(tally.get(profile, 0)) + 1
			seen += 1
		if identity != {"dev": 2, "test": 1, "design": 2} or shared != {"dev": 1, "test": 2, "design": 1}:
			return "%s: identity lines carry %s and shared lines %s; want dev 2, test 1, design 2 and dev 1, test 2, design 1" % [
				sub, identity, shared]
	if seen == 0:
		return "no line was read"
	var hidden_tally: Dictionary = {}
	for hidden in ResearchTree.hidden_line_ids():
		var hidden_profile: String = ResearchTree.hidden_line_profile(hidden)
		hidden_tally[hidden_profile] = int(hidden_tally.get(hidden_profile, 0)) + 1
	if hidden_tally != {"dev": 1, "test": 2, "design": 1}:
		return "the hidden lines carry %s; want dev 1, test 2, design 1" % hidden_tally

	var raw: Dictionary = ResearchTree.hidden_line_raw("line_hidden_self_serve")
	var bad: Dictionary = raw.duplicate(true)
	bad.erase("profile")
	if ProductLines.register_runtime_line(bad, "erp"):
		return "a line with no profile was registered"
	bad["profile"] = "devops"
	if ProductLines.register_runtime_line(bad, "erp"):
		return "a line with profile 'devops' was registered"
	if not ProductLines.register_runtime_line(raw, "erp") or ProductLines.work_profile("line_hidden_self_serve@erp") != "test":
		return "the authored hidden line did not register with its profile"
	if ProductLines.work_profile("line_nope") != "":
		return "an unknown line reads a profile"
	return ""


