# Kullanım: godot --headless -s crop.gd -- <json>; json: [{src,x,y,w,h,out}], 2x büyütür.
func _init() -> void:
	var args := OS.get_cmdline_user_args()
	var list: Array = JSON.parse_string(FileAccess.get_file_as_string(args[0]))
	for c: Dictionary in list:
		var img := Image.load_from_file(c.src)
		if img == null:
			print("CROPFAIL|", c.src)
			continue
		var r := Rect2i(int(c.x), int(c.y), int(c.w), int(c.h)).intersection(Rect2i(Vector2i.ZERO, img.get_size()))
		var part := img.get_region(r)
		part.resize(r.size.x * 2, r.size.y * 2, Image.INTERPOLATE_LANCZOS)
		var err := part.save_png(c.out)
		print("CROP|", c.out, "|", r, "|", err)
	quit()
EOF
